import java.util.*; class Payroll06{private double salary,bonus;Payroll06(double s){if(s<0){System.out.println("Warning: negative salary set to 0");s=0;}salary=s;}void creditBonus(double b){if(b>0)bonus+=b;}void deductTax(double p){if(p>=0&&p<=100)salary-=salary*p/100;}double net(){return salary+bonus;}} public class Week06Problem02{public static void main(String[]z){Scanner s=new Scanner(System.in);Payroll06 p=new Payroll06(s.nextDouble());p.creditBonus(s.nextDouble());p.deductTax(s.nextDouble());System.out.printf("Net salary: %.2f%n",p.net());}}